// Interpolated texts: the Ukrainian code builds them from parts, so they are matched as patterns.
// `t` translates a known phrase (or returns it unchanged); `list` translates each item of a list.
const PATTERNS = [
  [/^(\d+) з (\d+) завантажених профілів( · є наступна сторінка)?$/, (m, t, l) => ({ de: `${m[1]} von ${m[2]} geladenen Profilen${m[3] ? ' · es gibt eine weitere Seite' : ''}`, en: `${m[1]} of ${m[2]} loaded profiles${m[3] ? ' · there is another page' : ''}` })[l]],
  [/^ДО ПУБЛІКАЦІЇ: ЩЕ (\d+) ПУНКТІВ$/, (m, t, l) => ({ de: `VOR DER VERÖFFENTLICHUNG: NOCH ${m[1]} PUNKTE`, en: `BEFORE PUBLISHING: ${m[1]} ITEMS LEFT` })[l]],
  [/^Твоїх заявлених потреб ця людина закриває: (\d+) з (\d+)\. Її заявлених потреб закриваєш ти: (\d+) з (\d+)\. Рахуються лише заявлені навички й потреби, це не оцінка людини, довіри чи доходу\.$/, (m, t, l) => ({
    de: `Von deinen angegebenen Bedarfen deckt diese Person: ${m[1]} von ${m[2]}. Von ihren angegebenen Bedarfen deckst du: ${m[3]} von ${m[4]}. Gezählt werden nur angegebene Kompetenzen und Bedarfe – keine Bewertung von Mensch, Vertrauen oder Einkommen.`,
    en: `Of your declared needs, this person covers: ${m[1]} of ${m[2]}. Of their declared needs, you cover: ${m[3]} of ${m[4]}. Only declared skills and needs are counted – this is not a rating of the person, trust or income.` })[l]],
  [/^(Тобі|Іншій стороні): уточніть обсяг і доступність для «(.+)»\.$/, (m, t, l) => ({ de: `${t(m[1])}: Umfang und Verfügbarkeit für «${t(m[2])}» klären.`, en: `${t(m[1])}: clarify scope and availability for “${t(m[2])}”.` })[l]],
  [/^(Тобі|Іншій стороні): попросіть один релевантний приклад роботи для «(.+)»\.$/, (m, t, l) => ({ de: `${t(m[1])}: um ein passendes Arbeitsbeispiel für «${t(m[2])}» bitten.`, en: `${t(m[1])}: ask for one relevant work example for “${t(m[2])}”.` })[l]],
  [/^(Тобі|Іншій стороні): (.+)$/, (m, t, l, list) => `${t(m[1])}: ${list(m[2], ', ')}`],
  [/^(.+): вкажіть мову і формат співпраці\.$/, (m, t, l) => ({ de: `${t(m[1])}: Sprache und Kooperationsformat angeben.`, en: `${t(m[1])}: give a language and collaboration format.` })[l]],
  [/^(.+): вкажіть місто або онлайн і прийнятну відстань\.$/, (m, t, l) => ({ de: `${t(m[1])}: Stadt oder online und akzeptable Entfernung angeben.`, en: `${t(m[1])}: give a city or online and an acceptable distance.` })[l]],
  [/^(.+): уточніть період доступності\.$/, (m, t, l) => ({ de: `${t(m[1])}: Verfügbarkeitszeitraum klären.`, en: `${t(m[1])}: clarify the availability period.` })[l]],
  [/^(.+): актуальність профілю не підтверджена за останні 30 днів\.$/, (m, t, l) => ({ de: `${t(m[1])}: Aktualität des Profils in den letzten 30 Tagen nicht bestätigt.`, en: `${t(m[1])}: profile not confirmed as current in the last 30 days.` })[l]],
  [/^(\d+) з профілів: (.+)\.$/, (m, t, l) => ({ de: `${m[1]} Profile: ${t(m[2])}.`, en: `${m[1]} profiles: ${t(m[2])}.` })[l]],
  [/^(.+) · (Онлайн|(\d+) км між містами) · до (.+)$/, (m, t, l, list) => `${list(m[1], ', ')} · ${m[3] ? ({ de: `${m[3]} km zwischen den Städten`, en: `${m[3]} km between the cities` })[l] : 'Online'} · ${({ de: 'bis', en: 'until' })[l]} ${m[4]}`],
  [/^Заповни перед публікацією: (.+)$/, (m, t, l, list) => ({ de: 'Vor dem Veröffentlichen ausfüllen: ', en: 'Fill in before publishing: ' })[l] + list(m[1], '; ')],
  [/^Перед публікацією заповни умови співпраці: (.+)$/, (m, t, l, list) => ({ de: 'Vor dem Veröffentlichen die Kooperationsbedingungen ausfüllen: ', en: 'Fill in the collaboration terms before publishing: ' })[l] + list(m[1], '; ')],
  [/^(Можу дати|Потрібно мені|Потрібно|Мова розмови): (.+)$/, (m, t, l, list) => `${t(m[1])}: ${list(m[2], ', ')}`],
  [/^Місто: (.+)$/, (m, t, l) => ({ de: 'Stadt: ', en: 'City: ' })[l] + m[1]],
  [/^Показати один релевантний приклад роботи: (.+)\. Узгодити один вимірюваний результат, умови й прийняття\.$/, (m, t, l) => ({ de: `Ein passendes Arbeitsbeispiel zeigen: ${t(m[1])}. Ein messbares Ergebnis, Bedingungen und Abnahme vereinbaren.`, en: `Show one relevant work example: ${t(m[1])}. Agree one measurable result, terms and acceptance.` })[l]],
  [/^(Вхідний запит|Твоя пропозиція)( · .+)?$/, (m, t) => t(m[1]) + (m[2] || '')],
  [/^(\d+) км$/, m => `${m[1]} km`],
  [/^(\d+) хв · (.+)$/, (m, t, l) => `${m[1]} ${({ de: 'Min.', en: 'min' })[l]} · ${m[2]}`],
];

const collapse = text => String(text).replace(/\s+/g, ' ').trim();
export const PHRASES = { de: new Map(), en: new Map() };
for (const [uk, de, en] of ROWS) { PHRASES.de.set(collapse(uk), de); PHRASES.en.set(collapse(uk), en); }
PHRASES.de.set('Тобі', 'Dir'); PHRASES.en.set('Тобі', 'For you');
PHRASES.de.set('Іншій стороні', 'Der anderen Seite'); PHRASES.en.set('Іншій стороні', 'For the other side');
PHRASES.de.set('Потрібно', 'Brauche'); PHRASES.en.set('Потрібно', 'Need');

// Returns the translated text, or null when the text is not interface copy we know.
export function translatePhrase(text, locale) {
  const dict = PHRASES[locale];
  if (!dict) return null;
  const key = collapse(text);
  if (!key) return null;
  if (dict.has(key)) return dict.get(key);
  const t = s => dict.get(collapse(s)) ?? s;
  const list = (s, sep) => s.split(sep).map(part => t(part)).join(sep);
  for (const [re, build] of PATTERNS) {
    const m = key.match(re);
    if (m) return build(m, t, locale, list);
  }
  // Lists joined with " · " (hints, badges): translate the parts we know, keep the rest.
  if (key.includes(' · ')) {
    const parts = key.split(' · ');
    if (parts.some(part => dict.has(part))) return parts.map(t).join(' · ');
  }
  return null;
}
